def originated_quantity_this_turn(
    db: Any,
    dossier_id: int,
    turn: int,
    contract: Mapping[str, object],
) -> float:
    """当月 origin-linked canonical 效果的可数实物量（与合同 unit 同量纲）。"""
    did = int(dossier_id)
    current = int(turn)
    origin = f"dossier:{did}"
    delivery = contract.get("delivery") if isinstance(contract.get("delivery"), Mapping) else {}
    unit = str(delivery.get("unit") or "")
    fields = canonical_fields_for_delivery(unit=unit)
    qty = 0.0
    if "economy_moves" in fields:
        for item in db.list_economy_moves_for_dossier(did):
            if int(item.get("turn") or 0) != current:
                continue
            if not _delivery_matches_economy(item, delivery):
                continue
            try:
                qty += abs(float(item.get("delta") or 0))
            except (TypeError, ValueError):
                continue
    if "人物变更" in fields:
        action = str(delivery.get("person_action") or "").strip()
        rows = db.conn.execute(
            "SELECT id FROM person_logs WHERE origin_ref=? AND turn=? AND action=?",
            (origin, current, action),
        ).fetchall()
        qty += float(len(rows))
    if "region_delta" in fields:
        rows = db.conn.execute(
            "SELECT region_id, field, new_value, delta FROM region_logs "
            "WHERE origin_ref=? AND turn=?",
            (origin, current),
        ).fetchall()
        for row in rows:
            if _delivery_matches_region(row, delivery):
                qty += abs(float(row["delta"] or 0))
    return qty

def _normalize_cancellable(raw: object) -> str:
    """LLM 偶发臆造 cancellable 值（by_policy 之类），归一到合法白名单。"""
    val = str(raw or "").strip().lower()
    if val in ("decree", "never", "by_progress"):
        return val
    # 常见臆造映射
    if val in ("by_policy", "policy"):
        return "decree"
    if val in ("none", "no", "false"):
        return "never"
    if val in ("yes", "true", "auto"):
        return "by_progress"
    return "by_progress"  # 默认

def _secret_metadata_from_command(text: str) -> Tuple[List[str], int]:
    tags: List[str] = []
    deadline = 0
    for raw_line in (text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        m_tags = re.match(r"^(?:标签|tag|tags)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_tags:
            for item in re.split(r"[,，、/;；\s]+", m_tags.group(1)):
                cleaned = item.strip()
                if cleaned and cleaned not in tags:
                    tags.append(cleaned)
            continue
        m_deadline = re.match(r"^(?:期限|限期|deadline)\s*[：:]\s*(.+)$", line, flags=re.IGNORECASE)
        if m_deadline:
            match = re.search(r"([+-]?\d+)\s*(?:个)?月", m_deadline.group(1))
            if match:
                deadline = max(0, min(int(match.group(1)), 36))
    return tags, deadline

def commitment_natural_due_turn(row: Any) -> int:
    """承诺自身 due：段表 max due，否则 end_turn；0=无到期上限。"""
    try:
        keys = row.keys()  # sqlite3.Row
    except Exception:
        keys = list(row.keys()) if isinstance(row, dict) else []
    stages_raw = row["stages_json"] if "stages_json" in keys else (
        row.get("stages_json") if isinstance(row, dict) else None
    )
    stages = normalize_commitment_stages(stages_raw)
    if stages:
        return max(int(s["due_turn"]) for s in stages)
    try:
        end_turn = int(row["end_turn"] if "end_turn" in keys else (
            row.get("end_turn") if isinstance(row, dict) else 0
        ) or 0)
    except (TypeError, ValueError):
        end_turn = 0
    return end_turn if end_turn > 0 else 0

def _strip_trailing_comma(t: str, i: int, out: List[str], n: int) -> int:
    if t[i] == ",":
        k = i + 1
        while k < n and t[k] in " \t\r\n":
            k += 1
        if k < n and t[k] in "}]":
            return i + 1  # 丢弃结构尾逗号
    out.append(t[i])
    return i + 1

def _participant_roster_tables(self) -> List[tuple[str, set[str]]]:
    """List durable user tables that expose the common roster column."""
    tables = self.conn.execute(
        "SELECT name FROM sqlite_master WHERE type IN ('table', 'view') "
        "AND name NOT LIKE 'sqlite_%' ORDER BY name"
    ).fetchall()
    result: List[tuple[str, set[str]]] = []
    for row in tables:
        table = str(row["name"])
        if table in {"character_knowledge_sources", "decree_dossiers"}:
            continue
        columns = {
            str(column["name"])
            for column in self.conn.execute(
                "PRAGMA table_info(\"" + table.replace('"', '""') + "\")"
            ).fetchall()
        }
        if "participant_roster" in columns:
            result.append((table, columns))
    return result

def compute_budget_lines(
    db: GameDB, state: GameState, *, project_substrate_hub: bool = True
) -> Dict[str, Dict[str, list]]:
    """唯一定额预算源。返回 {"国库":{"income":[行],"expense":[行]},"内库":{...}}；
