        gk_tax, nk_huang, _ = calc_province_fiscal(state, db)
        hub_income_lines = [
            {"name": "田赋辽饷盐商", "amount": int(gk_tax),
             "note": "各省田赋+辽饷+盐税+商税（按腐败度/士绅阻力/民变动态折算）"}
        ]
        hub_expense_lines = []
    # #44 legacy 军饷=SUM(应发)。#1366 substrate 预算只陈列结算前拟拨事实：
    # 京运补与中央份额分开，均不受当月国库能力或未来转运损耗影响。
