            """
            SELECT id, manpower, salary_rate, owner_power, central_pay_share,
                   pay_source_region
            FROM armies
            WHERE owner_power = 'ming' AND is_tusi = 0 AND self_funded_pay = 0
              AND central_pay_share > 0
