def normalize_commitment_stages(raw: object) -> List[Dict[str, object]]:
    """Normalize structured stages payload → durable list.

    Accepts list/tuple of dicts, or a JSON array string. Non-JSON free text
    returns [] here (读侧宽容面)；写侧由 ``stages_to_json`` 响亮拒绝。

    分段承诺是机械事实（到期判账），只认显式结构化字段。引擎不得从 LLM 自由
    散文正则反推语义（ADR 0142 / 锚定宪法「机器只咬契约，不咬呈现」；owner
    2026-09-30「肯定不能让代码去扣」）。原 ``parse_staged_year_promise`` 的
    中文数词年诺捕获已随该裁定删除，无任何接缝再从散文抠年份。
    """
    if raw in (None, "", [], ()):
        return []
    data = raw
    if isinstance(raw, str):
        text = raw.strip()
        if not text or text in ("[]", "{}"):
            return []
        try:
            data = json.loads(text)
        except (TypeError, ValueError):
            return []
    if not isinstance(data, (list, tuple)):
        return []
    out: List[Dict[str, object]] = []
    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            continue
        try:
            due_turn = int(item.get("due_turn") or 0)
        except (TypeError, ValueError):
            continue
        if due_turn <= 0:
            continue
        try:
            stage_idx = int(item.get("stage_idx", idx))
        except (TypeError, ValueError):
            stage_idx = idx
        criterion = str(
            item.get("criterion_text") or item.get("criterion") or ""
        )
        origin_context = str(
            item.get("origin_context") or item.get("origin") or criterion or ""
        )
        if not criterion and origin_context:
            criterion = origin_context
        if not criterion:
            continue
        out.append({
            "stage_idx": stage_idx,
            "due_turn": due_turn,
            "criterion_text": criterion,
            "origin_context": origin_context or criterion,
        })
    out.sort(key=lambda s: (int(s["stage_idx"]), int(s["due_turn"])))
    return out

def normalize_audience_declaration(raw: object) -> Dict[str, object]:
    """转译 JSON → C0 声明形状；未知顶层键原样保留，交既有分派器 durable 拒收。

    不得在 normalize 静默删键——未知 section 的 ``invalid_shape`` 留痕是
    ``declaration_dispatch._record_unknown_sections`` 的唯一职责（ADR 0015）。
    """
    empty: Dict[str, object] = {k: [] for k in _ARRAY_SECTIONS}
    if not isinstance(raw, Mapping):
        return empty
    declaration: Dict[str, object] = {}
    for key in _DECLARATION_KEYS:
        if key not in raw:
            if key in _ARRAY_SECTIONS:
                declaration[key] = []
            elif key == "effects":
                declaration[key] = {}
            continue
        value = raw.get(key)
        if key == "effects":
            declaration[key] = {} if value is None else value
            continue
        if key == "protagonist":
            if value is None:
                continue
            declaration[key] = value
            continue
        if value is None:
            declaration[key] = []
        else:
            declaration[key] = value
    # 未知顶层键原样过手，供分派器逐项 invalid_shape；不在此过滤。
    for key, value in raw.items():
        sk = str(key)
        if sk in _DECLARATION_KEYS:
            continue
        declaration[sk] = value
    return declaration

def _apply_region_army_pay_tick(
    self,
    pay_rows: List[Dict[str, float | str]],
    result: Any,
    standalone_pay_component: Optional[Dict[str, float]] = None,
) -> None:
    if not pay_rows:
        return
    from ming_sim.flows import army_pay_morale_delta

    breakdown = result.breakdown or {}
    new_debt = float((breakdown.get("NewDebt") or {}).get("军饷欠", 0) or 0)
    repaid = float((breakdown.get("Repaid") or {}).get("军饷欠", 0) or 0)
    action_paid = float((breakdown.get("action还") or {}).get("军饷欠", 0) or 0)
    balances = {str(row["id"]): float(row["province_pay_arrears"]) for row in pay_rows}
    due_by_component = {str(row["id"]): float(row["due"]) for row in pay_rows}
    standalone_id = _STANDALONE_MILITARY_PAY_FUNNEL_ID
    if standalone_pay_component is not None:
        standalone_due = float(standalone_pay_component.get("due", 0.0) or 0.0)
        standalone_arrears = float(
            standalone_pay_component.get("province_pay_arrears", 0.0) or 0.0
        )
        if standalone_due > 0 or standalone_arrears > 0:
            balances[standalone_id] = standalone_arrears
            due_by_component[standalone_id] = standalone_due
    action_repaid_by_army = {str(row["id"]): 0.0 for row in pay_rows}
    new_debt_by_army = {str(row["id"]): 0.0 for row in pay_rows}
    surplus_repaid_by_army = {str(row["id"]): 0.0 for row in pay_rows}
    province_shortfalls = {str(row["id"]): 0.0 for row in pay_rows}
    if action_paid > 0:
        basis = sum(balances.values())
        if basis > 0:
            paid = min(action_paid, basis)
            for army_id, bal in list(balances.items()):
                share = paid * bal / basis
                if army_id in action_repaid_by_army:
                    action_repaid_by_army[army_id] = share
                balances[army_id] = max(0.0, bal - share)
    due_total = sum(due_by_component.values())
    if new_debt > 0 and due_total > 0:
        for component_id, due in due_by_component.items():
            shortfall = new_debt * due / due_total
            if component_id in province_shortfalls:
                province_shortfalls[component_id] = shortfall
                new_debt_by_army[component_id] = shortfall
            balances[component_id] += shortfall
    if repaid > 0:
        basis = sum(balances.values())
        if basis > 0:
            paid = min(repaid, basis)
            for army_id, bal in list(balances.items()):
                share = paid * bal / basis
                if army_id in surplus_repaid_by_army:
                    surplus_repaid_by_army[army_id] = share
                balances[army_id] = max(0.0, bal - share)
    state_row = self.conn.execute(
        "SELECT turn, year, period FROM game_state WHERE id = 1"
    ).fetchone()
    if state_row is None:
        state = self.load_state("")
        log_turn, log_year, log_period = state.turn, state.year, state.period
    else:
        log_turn = int(state_row["turn"])
        log_year = int(state_row["year"])
        log_period = int(state_row["period"])
    for row in pay_rows:
        army_id = str(row["id"])
        old_province_arrears = float(row["province_pay_arrears"])
        province_arrears = balances[army_id]
        central_arrears = float(row["central_pay_arrears"])
        central_shortfalls = getattr(self, "_current_month_central_pay_shortfalls", {})
        opening_arrears = getattr(self, "_current_month_pay_opening_arrears", {})
        total_shortfall = float(central_shortfalls.get(army_id, 0.0)) + province_shortfalls[army_id]
        old_total_arrears = float(
            opening_arrears.get(
                army_id,
                float(row["province_pay_arrears"]) + float(row["central_pay_arrears"]),
            )
        )
        old_morale = int(row["morale"])

def _commitment_arrears_gate_army_ids(row: sqlite3.Row) -> List[str]:
    ids: List[str] = []
    for key in _commitment_stop_gate(row):
        text = str(key)
        match = re.fullmatch(r"army\.([^.]+)\.arrears(?:\.sum)?", text)
        if not match:
            continue
        for army_id in match.group(1).split("|"):
            army_id = army_id.strip()
            if army_id and army_id not in ids:
                ids.append(army_id)
    return ids

def parse_responsible_bodies(raw: object) -> List[str]:
    """下议 responsible_bodies 唯一解析（暂存/admission/判后共用）。

    承 list/tuple，或 JSON 数组串，或「吏部、户部」类分隔串；空/不可用 → []。
    不在此做人物档语义；机关/职司个人名策略见 assert_responsible_bodies_org_only。
    """
    value = _parse_json_field(raw)
    if value is None:
        return []
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return []
        parts = [p.strip() for p in re_split_bodies(text) if p.strip()]
        out: List[str] = []
        for name in parts:
            if name not in out:
                out.append(name)
        return out
    if not isinstance(value, (list, tuple)):
        return []
    out = []
    for item in value:
        name = str(item or "").strip()
        if name and name not in out:
            out.append(name)
    return out

def parse_agent_json(raw: str, stage: str) -> Dict[str, Any]:
    text = strip_json_fence(raw)
    # 试 1：原文直解
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = None
    # 试 2：截 {...} 最外层再解
    if data is None:
        start = text.find("{")
        end = text.rfind("}")
        if start < 0 or end <= start:
            abort_llm_contract(stage, "没有返回 JSON object", raw)
        snippet = text[start : end + 1]
        try:
            data = json.loads(snippet)
        except json.JSONDecodeError:
            data = None
        # 试 3：净化 control char（\r\v\f\x00-\x1f 等）后再解
        if data is None:
            cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", snippet)
            try:
                data = json.loads(cleaned)
            except json.JSONDecodeError:
                data = None
        # 试 4：截取首个合法平衡的 {...} 子串（防 LLM 重发拼接）
        if data is None:
            depth = 0
            in_str = False
            esc = False
            best_end = -1
            for i, ch in enumerate(snippet):
                if esc:
                    esc = False
                    continue
                if ch == "\\" and in_str:
                    esc = True
                    continue
                if ch == '"':
                    in_str = not in_str
                    continue
                if in_str:
                    continue
                if ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        best_end = i
                        break
            if best_end > 0:
                first_block = snippet[: best_end + 1]
                first_block = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", first_block)
                try:
                    data = json.loads(first_block)
                except json.JSONDecodeError as error:
                    raise LLMContractError(
                        f"{stage} 输出不是合法 JSON：{error}\n原始输出：{raw[:800]}",
                        raw_value=raw,
                    ) from error
            else:
                raise LLMContractError(
                    f"{stage} 输出不是合法 JSON\n原始输出：{raw[:800]}",
                    raw_value=raw,
                )
    if not isinstance(data, dict):
        abort_llm_contract(stage, "顶层必须是 JSON object", raw)
    return data

def night_archive_metadata(
    ledgers: List[Dict[str, Any]], turns: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Purely derive archive labels from already-loaded durable-store rows."""
    summon_methods = [
        method
        for entry in ledgers if _is_command_entry(entry)
        for method in SUMMON_METHODS if method in (entry.get("tags") or [])
    ]
    # #1331/#1339：involved_people 投影缝复用 raw 非人判定（DRY 单真源）；
    # 禁 canon 后再滤（司礼监→王承恩）。写入侧 ledger 保留原文，投影侧只列真人。
    people: List[str] = []
    candidate_groups = [entry.get("person_names") or [] for entry in ledgers]
    candidate_groups.extend([turn.get("minister_name")] for turn in turns)
    for names in candidate_groups:
        for raw_name in names:
            name = str(raw_name or "").strip()
            if not name or name in people:
                continue
            if is_non_person_participant_name(name):
                continue
            people.append(name)
    summon_method = summon_methods[0] if summon_methods else ""
    return {
        # Summon methods remain machine tags; the container contract exposes the
        # player-facing audience type from this single production source.
        "audience_type": "越次召对" if summon_method == METHOD_YUECI else "召对",
        "involved_people": people,
    }

def _sponsor_names_for_commitment(db: Any, row: Any) -> List[str]:
    names: List[str] = []
    try:
        roster = json.loads(row["participant_roster"] or "[]")
    except (TypeError, ValueError):
        roster = []
    if isinstance(roster, list):
        for item in roster:
            if isinstance(item, dict) and item.get("tier") == "主办":
                cid = str(item.get("character_id") or "").strip()
                if cid:
                    names.append(cid)
    try:
        origin_ref = row["origin_ref"] if "origin_ref" in row.keys() else ""
    except Exception:
        origin_ref = ""
    did = parse_dossier_id(origin_ref)
    if did is not None:
        dossier = db.get_decree_dossier(int(did))
        if dossier is not None:
            for item in dossier.get("participant_roster") or []:
                if isinstance(item, dict) and item.get("tier") == "主办":
                    cid = str(item.get("character_id") or "").strip()
                    if cid and cid not in names:
                        names.append(cid)
            exec_id = str(dossier.get("executor_id") or "").strip()
            if exec_id and exec_id not in names:
                names.append(exec_id)
    return names

def _call_cli(self, prompt: str) -> Tuple[str, int]:
    """一次子进程。等多久算死归 transport 策略（设置页那一格的静默判死阈值）：
    出字的子进程不被任何总墙钟 SIGKILL，只有静默超阈值才判死重试。"""
    materials = str(getattr(self, "materials_dir", "") or "").strip() or None
    return _dispatch_cli_runner(
        self.backend,
        prompt,
        model=str(getattr(self, "id", "") or ""),
        reasoning_strength=(
            str(getattr(self, "reasoning_strength", "") or "").strip().lower() or None
        ),
        materials_dir=materials,
    )

def seed_guilt_counts_as_debt(seed_guilt: object) -> bool:
    """真相底只收结构化罪情。severity ∈ {轻, 中, 重} 才入罪谱。

    crime 是说明散文，不承重。解析失败、非对象、severity 为空或「无」，都不造罪。
    """
    if isinstance(seed_guilt, Mapping):
        guilt: object = seed_guilt
    else:
        text = str(seed_guilt or "").strip()
        if not text:
            return False
        try:
            parsed = json.loads(text)
        except (TypeError, ValueError):
            return False
        if not isinstance(parsed, Mapping):
            return False
        guilt = parsed
    severity = str(guilt.get("severity") or "").strip()
    return severity in _DEBT_SEVERITIES

def _agno_table_run_dicts(self, session_id: str) -> List[Dict[str, Any]]:
    if not self._table_exists("agno_runs"):
        return []
    rows = self.conn.execute(
        """
        SELECT run_id, run_data FROM agno_runs
        WHERE session_id = ?
        ORDER BY run_index ASC, created_at ASC, run_id ASC
        """,
        (session_id,),
    ).fetchall()
    out: List[Dict[str, Any]] = []
    for row in rows:
        rid = row["run_id"]
        if rid is None:
            continue
        payload: Dict[str, Any] = {"run_id": str(rid)}
        raw = row["run_data"]
        if raw not in (None, ""):
            try:
                decoded = json.loads(raw) if isinstance(raw, str) else raw
            except (TypeError, ValueError):
                decoded = None
            if isinstance(decoded, dict):
                payload = dict(decoded)
                payload["run_id"] = str(rid)
        out.append(payload)
    return out

def _dossier_row(cls, row: Any) -> Dict[str, object]:
    out = dict(row)
    out["id"] = int(out["id"])
    out["region_id"] = str(out.get("region_id") or "")
    for key in (
        "source_chat_turn_id", "pending_action_id", "directive_id",
        "due_turn", "created_turn", "created_year", "created_period",
        "held_turn", "affair_id",
    ):
        out[key] = int(out.get(key) or 0)
    if out.get("secret_order_id") is not None:
        out["secret_order_id"] = int(out["secret_order_id"])
    out["rescript_pending"] = bool(out.get("rescript_pending"))
    try:
        payload = json.loads(out.get("payload_json") or "{}")
    except (TypeError, ValueError) as exc:
        raise ValueError(f"案卷#{out['id']} payload_json 无效") from exc
    if not isinstance(payload, dict):
        raise ValueError(f"案卷#{out['id']} payload_json 非对象")
    out["payload"] = payload
    out["mode"] = cls._normalize_dossier_mode(
        payload["mode"] if "mode" in payload else "ordinary"
    )
    try:
        stigma = json.loads(out.get("stigma_json") or "[]")
    except (TypeError, ValueError) as exc:
        raise ValueError(f"案卷#{out['id']} stigma_json 无效") from exc
    if not isinstance(stigma, list):
        raise ValueError(f"案卷#{out['id']} stigma_json 非列表")
    out["stigma"] = stigma
    try:
        roster = json.loads(out.get("participant_roster") or "[]")
    except (TypeError, ValueError) as exc:
        raise ValueError(f"案卷#{out['id']} participant_roster 无效") from exc
    if not isinstance(roster, list):
        raise ValueError(f"案卷#{out['id']} participant_roster 非列表")
    out["participant_roster"] = roster
    try:
        extension = json.loads(out.get("extension_json") or "{}")
    except (TypeError, ValueError) as exc:
        raise ValueError(f"案卷#{out['id']} extension_json 无效") from exc
    if not isinstance(extension, dict):
        raise ValueError(f"案卷#{out['id']} extension_json 非对象")
    signal = extension.get("execution_signal")
    if signal is not None and not isinstance(signal, dict):
        raise ValueError(f"案卷#{out['id']} execution_signal 非对象")
    out["execution_signal"] = signal
    return out

def _validate_participant_roster_references(
    self, roster: Iterable[Mapping[str, object]],
) -> None:
    """Enforce ADR 0053 character primary-key references at the DB write seam."""
    entries = list(roster)
    referenced = {
        str(value).strip()
        for item in entries
        for value in (item.get("character_id"), item.get("delegator_id"))
        if str(value or "").strip()
    }
    if not referenced:
        return
    placeholders = ",".join("?" for _ in referenced)
    known = {
        str(row["name"])
        for row in self.conn.execute(
            f"SELECT name FROM characters WHERE name IN ({placeholders})",
            tuple(referenced),
        ).fetchall()
    }
    from ming_sim.participant_roster import is_non_person_participant_name

    def _roster_ref_error(label: str, name: str) -> ValueError:
        # #1380：拒「皇帝」等非人通称时给人话提示，禁裸「参与人物不存在：皇帝」
        if is_non_person_participant_name(name):
            return ValueError(
                f"{label}不存在：{name}。"
                f"人物参与人须为朝堂名册中的大臣姓名，"
                f"不可填「{name}」等非人通称或机构名。"
            )
        return ValueError(
            f"{label}不存在：{name}。"
            f"请填写朝堂名册中已有的大臣姓名。"
        )

    for item in entries:
        character_id = str(item.get("character_id") or "").strip()
        delegator_id = str(item.get("delegator_id") or "").strip()
        if character_id not in known:
            raise _roster_ref_error("参与人物", character_id)
        if delegator_id and delegator_id not in known:
            raise _roster_ref_error("委派人", delegator_id)

def _collect_compliant_promulgation_items(
    batch: object,
    db: GameDB,
    *,
    proposed_modes: Dict[int, str],
    prepared_context: Optional[Dict[str, object]],
    reviewed_dossier_ids: Optional[set[int]],
) -> List[Dict[str, object]]:
    """从不合规整批中收集单项已过闸的判决（证据保留，不落判、不伪造缺案）。"""
    if not isinstance(batch, list):
        return []
    good: List[Dict[str, object]] = []
    seen: set[int] = set()
    for candidate in batch:
        try:
            valid = _validate_promulgation_verdict_item(
                candidate, db,
                proposed_modes=proposed_modes,
                prepared_context=prepared_context,
            )
        except LLMContractError:
            continue
        dossier_id = int(valid["dossier_id"])
        if reviewed_dossier_ids is not None and dossier_id not in reviewed_dossier_ids:
            continue
        if dossier_id in seen:
            continue
        seen.add(dossier_id)
        good.append(valid)
    return good

def _next_attempt(turn: int) -> int:
    """同 turn 的下一个 attempt 序号：既有目录数字后缀 max+1（决定 5，不从 DB 取）。

    len+1 在非连续目录（玩家发包后删过早期 attempt）下会撞既有名而静默覆盖诊断孤本；
    不可解析的后缀忽略。
    """
    root = error_packs_root()
    if not root.exists():
        return 1
    prefix = f"turn{int(turn)}_attempt"
    highest = 0
    for p in root.iterdir():
        if not (p.is_dir() and p.name.startswith(prefix)):
            continue
        try:
            highest = max(highest, int(p.name[len(prefix):]))
        except ValueError:
            continue
    return highest + 1

def _apply_metric_dict(
    state: GameState, metric_delta: Dict[str, object], caps: Optional[Dict[str, int]] = None,
    db: Optional[GameDB] = None,
) -> Dict[str, int]:
    # 传 db 时，民心/皇威 增量先过帝国修正 %（base>=0 ×(1+net/100)，base<0 ×(1-net/100)），再夹 cap。
    mods = db.legacy_modifiers(state) if db is not None else {}
    applied: Dict[str, int] = {}
    # isinstance 守卫：issue-effect 路径（enrich/stored，未过 validate_delta_shape）的 metrics 可能
    # 被 LLM 给成真值非 dict，`or {}` 兜不住→.items() 抛 AttributeError 崩回合（#117 同类，顶层 delta
    # 已由 validate_delta_shape 保 dict，此守卫只对未验证的 issue-effect 调用点生效、不误伤）。
    metric_delta = metric_delta if isinstance(metric_delta, dict) else {}
    for key, val in metric_delta.items():
        if key not in ISSUE_METRIC_KEYS:
            continue
        try:
            d = int(val)
        except (TypeError, ValueError):
            continue
        net_pct = int(mods.get(key, 0) or 0)
        if net_pct and db is not None:
            d = db.apply_legacy_pct(d, net_pct)
        if caps and key in caps:
            cap = caps[key]
            if d > cap:
                d = cap
            elif d < -cap:
                d = -cap
        if d == 0:
            continue
        state.metrics[key] = int(state.metrics.get(key, 0)) + d
        applied[key] = applied.get(key, 0) + d
    return applied

def _invalid_monthly_person_rating_reason(effect: Dict[str, object]) -> str:
    for key in ("人物变更", "person_changes"):
        raw = effect.get(key)
        if not isinstance(raw, list):
            continue
        for item in raw:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or item.get("人物") or "").strip()
            action = str(item.get("动作") or item.get("action") or "").strip()
            if not name or action != "评定":
                continue
            loyalty = item.get("loyalty")
            if isinstance(loyalty, bool) or not isinstance(loyalty, int) or loyalty == 0:
                return f"{key}.评定 loyalty 须为非零整数增量"
    raw_character = effect.get("character")
    if isinstance(raw_character, list):
        for item in raw_character:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or item.get("人物") or "").strip()
            if not name or "loyalty" not in item:
                continue
            loyalty = item.get("loyalty")
            if isinstance(loyalty, bool) or not isinstance(loyalty, int) or loyalty == 0:
                return "character.loyalty 须为非零整数增量"
    return ""

def _recurring_funding_label_tokens(*values: object) -> set[str]:
    """ADR0027 科目名 stem：key 去 _base/_rate；无 reason；无词义剥离。

    display/category 是自由标签，仅因 ADR0027 历史双扣「账户+科目名」轴获准作匹配，
    不因其在结构化 JSON 内便升格为形式身份。purpose（补饷/其它枚举）不是科目名。
    """
    tokens: set[str] = set()
    for value in values:
        raw = str(value or "").strip()
        if not raw:
            continue
        key_stem = raw
        if key_stem.endswith("_base") or key_stem.endswith("_rate"):
            key_stem = key_stem.rsplit("_", 1)[0]
        if key_stem:
            tokens.add(key_stem)
    return tokens

def run_terminal_state_pass() -> None:
    for ev in c.events:
        if ev.id in terminal_refs or ev.trigger_year <= 0:
            continue
        if _event_window_expired(ev, state):
            db.mark_event_expired(state, ev.id, commit=False)
            terminal_refs.add(ev.id)
            terminalized.append({"id": ev.id, "title": ev.title, "terminal_state": "expired"})
            continue
        dead_subjects = _dead_person_core_subjects(ev, db)
        if dead_subjects:
            reason = f"人物核心主体永久死亡：{', '.join(dead_subjects)}"
            db.mark_event_obsolete(state, ev.id, reason=reason, commit=False)
            terminal_refs.add(ev.id)
            terminalized.append({"id": ev.id, "title": ev.title, "terminal_state": "obsolete"})
            continue
        if not _event_window_open(ev, state):
            continue
        if not _gate_passed(ev.trigger_gate, state.metrics, db):
            avoided_reason = _person_core_avoided_reason(ev, state, db)
            if avoided_reason:
                db.mark_event_avoided(state, ev.id, reason=avoided_reason, commit=False)
                terminal_refs.add(ev.id)
                terminalized.append({"id": ev.id, "title": ev.title, "terminal_state": "avoided"})

    for ev in c.seed_events:
        if ev.id in terminal_refs:
            continue
        if _event_window_expired(ev, state):
            db.mark_event_expired(state, ev.id, commit=False)
            terminal_refs.add(ev.id)
            terminalized.append({"id": ev.id, "title": ev.title, "terminal_state": "expired"})

    terminalized.extend(apply_event_cascading_invalidations(state, db, commit=False))

def normalize_openai_base_url(base_url: str) -> str:
    base = base_url.rstrip("/")
    if base.endswith("/v1"):
        return base
    return f"{base}/v1"

def resolve_special_region_alias(token: str) -> Optional[str]:
    """Exact id or special-alias token → region_id；未知返回 None（不模糊匹配）。"""
    raw = str(token or "").strip()
    if not raw:
        return None
    if raw in REGION_SPECIAL_ALIASES:
        return raw
    key = compact_name(raw)
    if not key:
        return None
    if key in REGION_SPECIAL_ALIASES:
        return key
    for region_id, aliases in REGION_SPECIAL_ALIASES.items():
        if key == compact_name(region_id):
            return region_id
        for alias in aliases:
            if key == compact_name(alias):
                return region_id
    return None

def _match_rank_rule(
    title: str, table: dict[str, Any], required_field: str
) -> Optional[dict[str, Any]]:
    """Return the longest matching stem that defines the requested behavior."""
    text = str(title or "").strip()
    if not text:
        return None
    best: Optional[dict[str, Any]] = None
    best_score = (-1, -1)
    for rule in _iter_rank_rules(table):
        if required_field not in rule:
            continue
        # Leverage-bearing rules describe substantive titles.  Rank-only rules also
        # contain institutional/category fallbacks such as 翰林院 and 锦衣卫.
        title_specific = int(
            required_field == "rank_band" and "leverage_multiplier" in rule
        )
        for stem in rule.get("stems") or []:
            token = str(stem or "").strip()
            if not token or token not in text:
                continue
            score = (title_specific, len(token))
            if score > best_score:
                best = rule
                best_score = score
    return best

def _on_event(event: Any) -> None:
    name = type(event).__name__
    if name == "RunContent" or getattr(event, "event", None) == "RunContent":
        piece = str(getattr(event, "content", "") or "")
        if piece:
            chunks.append(piece)
            stream_emit(piece)
    if name in ("RunOutput", "RunCompletedEvent"):
        run_output_box.clear()
        run_output_box.append(event)

def declared_report_action_origin(raw: object, *, base: str) -> str:
    """月报 origin 只留下人物已经声明的睁眼闭眼或带私货。

    同派／敌派是监督事实，不是行动。未声明、或声明里夹着别的记号，都不写成行动。
    """
    text = str(raw or "").strip()
    if not text:
        return base
    if text.startswith("dossier-report:"):
        _root, parsed = parse_report_origin(text)
        marks = [mark for mark in parsed if mark in DECLARED_REPORT_ACTION_MARKS]
        return compose_report_origin(base, marks)
    parts = [part.strip() for part in text.split(ORIGIN_MARK_SEP) if part.strip()]
    marks = [part for part in parts if part in DECLARED_REPORT_ACTION_MARKS]
    return compose_report_origin(base, marks)

