def presence_roster(db: Any, night_id: int) -> List[Dict[str, Any]]:
    """Project everyone who entered this night, in first-entry order, with current presence."""
    present: set[str] = set()
    ordered: List[str] = []
    seen: set[str] = set()
    for entry in list_ledger(db, int(night_id)):
        delta = _presence_delta(entry)
        names = [str(name) for name in entry.get("person_names") or []]
        if delta == PRESENCE_ENTER:
            for name in names:
                if name not in seen:
                    seen.add(name)
                    ordered.append(name)
        _apply_presence(present, entry)
    return [{"name": name, "present": name in present} for name in ordered]

def _extract_ref_ids(items: object, *, prefixes: Sequence[str]) -> Set[int]:
    """统一 walker：从 list[dict] 抽 issue/dossier 引用 id。

    认 key 集合 + target_id 前缀 + origin_ref/来源引用；禁纯数字 target_id 误吞为 dossier。
    信用写端（#628）与哭谏识别共此单源，禁平行复制。
    """
    out: Set[int] = set()
    if not isinstance(items, list):
        return out
    id_keys_by_prefix = {
        "issue": ("issue_id", "id", "commitment_ref"),
        "dossier": ("dossier_id", "revoke_target_dossier_id"),
    }
    keys: Set[str] = set()
    for p in prefixes:
        keys.update(id_keys_by_prefix.get(p, ()))
    for it in items:
        if not isinstance(it, dict):
            continue
        for key in keys:
            raw = it.get(key)
            if raw in (None, ""):
                continue
            # issue walker 的裸 id 可能与 dossier_id 键冲突时仅在对应 prefix 下启用
            if key in {"id"} and "issue" not in prefixes:
                continue
            try:
                out.add(int(raw))
            except (TypeError, ValueError):
                continue
        tid = str(it.get("target_id") or "").strip()
        for p in prefixes:
            if tid.startswith(f"{p}:"):
                try:
                    out.add(int(tid.split(":", 1)[1]))
                except (TypeError, ValueError):
                    pass
        for key in ("origin_ref", "来源引用"):
            ref = str(it.get(key) or "").strip()
            for p in prefixes:
                if p == "issue":
                    m = _ISSUE_REF_RE.match(ref)
                    if m:
                        out.add(int(m.group(1)))
                elif p == "dossier":
                    m = _DOSSIER_REF_RE.match(ref)
                    if m:
                        out.add(int(m.group(1)))
    return out

