def settle_exposure_from_canonical_actions(db: Any, state: Any, applied: Mapping[str, object]) -> int:
    """只凭 canonical applier 已成功落库的结果消费待办。"""
    consumed = 0
    for todo in db.list_next_audience_todos(status="pending"):
        if todo.get("entry_kind") != ENTRY_KIND:
            continue
        payload = todo.get("payload_json") or {}
        did = int(payload.get("dossier_id") or 0)
        # The same row remains the durable reminder only while the real gap exists.
        if payload.get("decision") == "禁摊派":
            pay_fact = army_pay_fact_for_dossier(db, did) or {}
            if float(pay_fact.get("arrears") or 0) <= 0:
                db.mark_next_audience_todo_status(int(todo["id"]), "consumed", commit=False)
                consumed += 1
            continue
        if payload.get("decision"):
            continue
        origin = f"dossier:{did}"
        dossier = db.get_decree_dossier(did) or {}
        actors = {str(dossier.get("executor_id") or "").strip()}
        for participant in dossier.get("participant_roster") or []:
            if isinstance(participant, Mapping) and participant.get("tier") in {"主办", "协办"}:
                actors.add(str(participant.get("character_id") or "").strip())
        actors.discard("")
        successful = lambda x: isinstance(x, Mapping) and not x.get("rejected")
        # Identity is the successfully promulgated case-bound dossier, never an
        # unrelated fiscal receipt with a convenient shape.
        pay_fact = army_pay_fact_for_dossier(db, did) or {}
        prohibition = active_prohibition_dossier(db, did)
        stopped = prohibition is not None
        if prohibition is not None:
            # The canonical prohibition owns the durable, idempotent rollback receipt.
            from ming_sim.issues import neutralize_covert_fiscal_effects
            neutralize_covert_fiscal_effects(
                db, state, exposed_dossier_id=did,
                prohibition_dossier_id=int(prohibition["id"]),
            )
        levy_transfer = any(
            is_actual_population_transfer(x)
            and x.get("origin_ref") == origin and x.get("reason") == "摊派"
            for x in applied.get("population_transfers") or []
        )
        covert_effect = any(
            successful(x) and x.get("applied") is True
            and x.get("origin_ref") == origin and x.get("beyond_intent") is True
            for key in ("economy_moves", "fiscal_changes", "fiscal_creates", "fiscal_removes")
            for x in applied.get(key) or []
        )
        person_changes = list(applied.get("applied_person_changes") or [])
        person_changes += list((applied.get("issue_summary") or {}).get("applied_person_changes") or [])
        punished = any(
            successful(x) and x.get("动作") in {"处置", "罢黜"}
            and str(x.get("name") or "") in actors for x in person_changes
        )
        paid_cost = any(
            successful(x)
            and str(x.get("origin") or "").startswith(f"{origin}:relation:")
            and ({str(x.get("source") or ""), str(x.get("target") or "")} & actors)
            for x in applied.get("relation_edge_event_resolutions") or []
        )
        decisions = [
            name for name, matched in (
                ("禁摊派", stopped), ("默许", levy_transfer and covert_effect),
                ("查办", punished and paid_cost),
            ) if matched
        ]
        if len(decisions) != 1:
            continue
        decision = decisions[0]
        # 禁令的真实后果是欠饷缺口继续顶在御前，故保留同一 pending 行而非造第二 dispatcher。
        reopened = (
            decision == "禁摊派" and float(pay_fact.get("arrears") or 0) > 0
        )
        status = "pending" if reopened else "consumed"
        db.mark_next_audience_todo_status(
            int(todo["id"]), status,
            payload_patch={"decision": decision, "decided_turn": int(state.turn),
                           "shortfall_reopened": reopened}, commit=False,
        )
        consumed += 1

def apply_investigation_spoliation(
    db: Any,
    *,
    target: str,
    fact_key: str,
    effect: str = "harder",
    knowledge_source: str = "",
    dossier_id: int = 0,
    origin_ref: str = "",
    turn: Optional[int] = None,
    commit: bool = False,
) -> Dict[str, object]:
    """毁证落账口：按对应事实改可查性，不团灭、不改真相底。

    知情与反应归人物（P6）：本函数只处理其**真实选择**的后果，并且要求人物确实
    经真实传话声明知情（knowledge_source）——未知情不替其毁证，知情也不强制毁证。
    'gone' 之后该事实永不可查——关案重开、另起新案都不恢复（真源在 (target, fact_key)）。
    """
    name = str(target or "").strip()
    key = str(fact_key or "").strip()
    if not name or not key:
        raise CovertContractError("毁证落账缺少调查对象或事实键")
    if not _investigation_knowledge_known(
        db, name, knowledge_source, dossier_id=int(dossier_id or 0),
    ):
        # fail-closed：无真实传话声明就不毁证，也不改任何实证。
        return {"target": name, "fact_key": key, "applied": False,
                "reason": "无真实关系网知情来源，不代其毁证"}
    if key not in live_investigation_fact_keys(db, name):
        # 只毁真实存在的事实；不得凭空毁一条不存在的罪（也无从"恢复"）。
        return {"target": name, "fact_key": key, "applied": False,
                "reason": "该事实不在真相底 live 集内"}
    row = db.record_investigation_spoiled_fact(
        target_name=name, fact_key=key, turn=turn, effect=effect,
        origin_ref=origin_ref, commit=False,
    )
    if commit and int(getattr(db.conn, "_atomic_depth", 0) or 0) == 0:
        db.conn.commit()
    return {"target": name, "fact_key": key, "applied": True, "effect": str(effect),
            "knowledge_source": str(knowledge_source or ""),
            "row_id": row.get("id")}

def _coerce_bool_flag(raw: object) -> bool:
    if isinstance(raw, bool):
        return raw
    if raw is None:
        return False
    if isinstance(raw, (int, float)):
        return raw != 0
    return str(raw).strip().lower() in {"1", "true", "yes", "y", "是", "土司", "自养", "自养军饷"}

def next_pool_portrait_id(self, prefix: str = "minister_pool_") -> str:
    """分配下一个预设头像 ID（顺序递增，不循环）。
    minister_pool: 60 个槽；consort_pool: 20 个槽。
    实际可用槽位 = web/public/portraits/<prefix><N>.png 真存在的编号集合（中途删图会跳过缺号）。
    发行包只带 web/dist；public 不存在时回退扫 web/dist/portraits。
    全部用完后再回退到递增（前端 onError fallback 占位符）。"""
    rows = self.conn.execute(
        "SELECT portrait_id FROM characters WHERE portrait_id LIKE ?",
        (prefix + "%",),
    ).fetchall()
    used = set()
    for r in rows:
        try:
            used.add(int(r["portrait_id"].replace(prefix, "")))
        except ValueError:
            pass
    # 扫真实存在的图编号：源码优先 public；发行包只带 Vite 产物 dist。
    from pathlib import Path
    from ming_sim.paths import bundled_path
    available: set[int] = set()
    for portraits_dir in (
        Path(bundled_path("web", "public", "portraits")),
        Path(bundled_path("web", "dist", "portraits")),
    ):
        if not portraits_dir.is_dir():
            continue
        for p in portraits_dir.glob(f"{prefix}*.png"):
            suffix = p.stem[len(prefix):]
            if suffix.isdigit():
                available.add(int(suffix))
        if available:
            break
    free = sorted(available - used)
    if free:
        return f"{prefix}{free[0]}"
    # 真实图全用完：递增分配，但跳过已知中途缺号（如手动删过的 consort_pool_14）。
    # 编号上限：available 最大值 + 缺号集；超出后继续递增（前端 onError fallback 占位符）。
    max_known = max(available, default=0)
    missing = {n for n in range(1, max_known + 1) if n not in available}
    n = 1
    while n in used or n in missing:
        n += 1
    return f"{prefix}{n}"

def _validate_promulgation_verdict_item(
    row: object, db: GameDB,
    *,
    proposed_modes: Optional[Dict[int, str]] = None,
    prepared_context: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """The single shape/identity authority for one provider verdict."""
    if not isinstance(row, dict):
        raise LLMContractError("颁布判决须为对象")
    if str(row.get("decision") or "") not in {"promulgated", "rejected"}:
        raise LLMContractError("颁布判决 decision 只能为 promulgated 或 rejected")
    dossier_id = row.get("dossier_id")
    if (isinstance(dossier_id, bool) or not isinstance(dossier_id, int)
            or not 0 < dossier_id <= 2 ** 63 - 1):
        raise LLMContractError("颁布判决 dossier_id 必须为有效 SQLite 正整数")

    context = prepared_context or {}
    if prepared_context is not None:
        faction_names = {
            str(item["name"]) for item in context.get("factions", [])
            if isinstance(item, dict)
        }
        class_names = {str(item) for item in context.get("classes", [])}
        gatekeeper_ids = {
            str(item["name"]) for item in context.get("gatekeepers", [])
            if isinstance(item, dict) and isinstance(item.get("name"), str)
        }
        context_dossiers = {
            int(item["id"]): item for item in context.get("dossiers", [])
            if isinstance(item, dict) and isinstance(item.get("id"), int)
        }
    else:
        faction_names = {
            str(item["name"]) for item in db.conn.execute("SELECT name FROM factions")
        }
        class_names = {
            str(item["name"])
            for item in db.conn.execute("SELECT DISTINCT name FROM classes")
        }
        gatekeeper_ids = {
            str(item["name"])
            for item in db.conn.execute("SELECT name FROM characters")
        }
        context_dossiers = {}

    modes = proposed_modes or {}
    rejection_only_fields = {
        "blocked_layer", "primary_opponents", "gatekeeper_id", "reason",
        "criteria_snapshot", "midzhi_unpromulgatable",
    }
    try:
        decision = row.get("decision")
        mode = modes.get(dossier_id) if isinstance(dossier_id, int) else None
        # Work on a shallow copy: 顺颁 may strip LLM noise without mutating caller input.
        item: Dict[str, object] = dict(row)
        if decision == "promulgated":
            # #1397 / r6: 颁布判官 LLM 常在 decision=promulgated 上夹带打回形解释字段
            # （reason/gatekeeper_id/primary_opponents/criteria_snapshot 等）。decision 已
            # 钉顺颁，这些字段是产出噪声而非语义；硬拒会在 pre_settle 落 settling 后
            # SettlementAbort 卡死整月。剥离已知噪声， downstream 按干净顺颁继续。
            # 真正未知键与打回契约仍硬拒（见下方 exact-key / rejection 校验）。
            for key in rejection_only_fields:
                item.pop(key, None)
            item.pop("legal_reason_code", None)
            # ordinary/midzhi 顺颁均省略 affected_parties（#657 §C.8 later-wins：中旨不猜派）。
            item.pop("affected_parties", None)
        elif mode == "midzhi" and decision == "rejected":
            # 中旨打回：剥离猜派字段；正式离心归 M12。
            item.pop("affected_parties", None)
        marker = item.get("midzhi_unpromulgatable", False)
        if not isinstance(marker, bool):
            raise ValueError("中旨亦不可颁标记必须为 bool")
        if marker:
            if mode is not None:
                if decision != "rejected" or mode != "midzhi":
                    raise ValueError("中旨亦不可颁只能标记中旨打回判决")
            elif decision != "rejected":
                raise ValueError("中旨亦不可颁只能标记打回判决")
        if any(isinstance(key, str) and key.startswith("resistance_") for key in item):
            raise ValueError("颁布判决不得携带阻力数值字段")

def _load_optional_json(row: Any, column: str) -> object:
    if column not in row.keys() or row[column] is None:
        return None
    return json.loads(row[column])

def pointing_at(
    self,
    origin_refs: Iterable[str],
    *,
    subject_kind: str | None = None,
) -> tuple[TextualFact, ...]:
    refs = [str(ref).strip() for ref in origin_refs if str(ref).strip()]
    if not refs:
        return ()
    placeholders = ",".join("?" for _ in refs)
    sql = (
        "SELECT id, subject_kind, subject_id, year, period, turn, body, origin_ref "
        "FROM textual_facts WHERE origin_ref IN (" + placeholders + ")"
    )
    params: list[object] = list(refs)
    if subject_kind is not None:
        kind = str(subject_kind or "").strip()
        if kind not in TEXTUAL_FACT_SUBJECT_KINDS:
            raise ValueError(
                f"textual fact subject_kind must be one of {sorted(TEXTUAL_FACT_SUBJECT_KINDS)}"
            )
        sql += " AND subject_kind = ?"
        params.append(kind)
    sql += " ORDER BY year ASC, period ASC, id ASC"
    return tuple(_row_to_fact(row) for row in self._conn.execute(sql, params).fetchall())

def resolve_lead_executors(
    *,
    action_type: object = "",
    target_id: object = "",
    payload: Optional[Mapping[str, object]] = None,
    participant_roster: object = None,
) -> Dict[str, object]:
    """确定性点将路由（ADR 0117 净新契约 a）：返回结构化路由结果。

    leads 有序去重；signal.code='idle_start'＝怠办起步（任免无被任命者）。
    #1778 决定 3：没点将时代码不配人——名单由拟票大臣写在票拟里，
    空 leads 即空，不查职司表、不走降档链。
    """
    canonical_payload = payload or {}
    coverage = classify_execution_coverage(action_type, canonical_payload)
    if coverage is None:
        return {
            "coverage": None, "route": "excluded", "leads": [], "signal": None,
        }

    # ① 任免：执行主体＝被任命者本人
    if coverage == "appointment":
        who = str(target_id or "").strip()
        if who:
            return {
                "coverage": coverage,
                "route": "appointment_self",
                "leads": [who],
                "signal": None,
            }
        return {
            "coverage": coverage,
            "route": "appointment_self",
            "leads": [],
            "signal": {"code": "idle_start", "reason": "appointment_without_target"},
        }

    # ② 点将优先：规范化 assignee 是生产点将；0053 roster 是同义结构入口。
    assignee = str(canonical_payload.get("assignee_id") or "").strip()
    if assignee:
        return {
            "coverage": coverage, "route": "named",
            "leads": [assignee], "signal": None,
        }
    roster = participant_roster if isinstance(participant_roster, list) else []
    named: List[str] = []
    seen: set = set()
    for entry in roster:
        if not isinstance(entry, dict):
            continue
        if str(entry.get("tier") or "").strip() != "主办":
            continue
        name = str(entry.get("character_id") or "").strip()
        if name and not str(entry.get("delegator_id") or "").strip() and name not in seen:
            seen.add(name)
            named.append(name)
    return {
        "coverage": coverage,
        "route": "named" if named else "unassigned",
        "leads": named,
        "signal": None,
    }

def _fiscal_config_rate(db: GameDB, key: str) -> float:
    cfg = db.get_fiscal_config()
    minimum = db.fiscal_config_minimum_value(key)
    if key not in cfg and (
        minimum is not None or db.fiscal_config_loss_rate_pair(key) is not None
    ):
        raise ValueError(f"fiscal_config.{key} 缺失")
    raw = cfg.get(key, 0)
    if isinstance(raw, bool):
        raise ValueError(f"fiscal_config.{key} 非法：{raw!r}")
    try:
        value = float(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"fiscal_config.{key} 非数值：{raw!r}") from exc
    if not math.isfinite(value) or value < 0 or value > 100:
        raise ValueError(f"fiscal_config.{key} 越界：{raw!r}")
    if minimum is not None and value < minimum:
        raise ValueError(f"fiscal_config.{key} 低于结构地板 {minimum}：{raw!r}")
    return value / 100.0

