def _fiscal_levy_mark_provisional(meta: Dict[str, object]) -> None:
    raw = meta.get("provisional", [])
    if isinstance(raw, list):
        provisional = [str(item) for item in raw]
    else:
        provisional = []
    seen = set(provisional)
    for key in sorted(_FISCAL_LEVY_PROVISIONAL_KEYS):
        if key not in seen:
            provisional.append(key)
            seen.add(key)
    meta["provisional"] = provisional

def _person_core_avoided_reason(ev: Event, state: GameState, db: GameDB) -> str:
    subjects = [str(name) for name in (getattr(ev, "person_core_subjects", []) or []) if str(name)]
    if not subjects:
        return ""
    gate = ev.trigger_gate or {}
    subject_prefixes = tuple(f"character.{name}." for name in subjects)
    subject_gate = {
        key: cond
        for key, cond in gate.items()
        if any(str(key).startswith(prefix) for prefix in subject_prefixes)
    }
    if not subject_gate:
        return ""
    if _gate_passed(subject_gate, state.metrics, db):
        return ""
    return f"人物核心前提已被玩家处理：{', '.join(subjects)}"

def identity_title_for_allegiance(item: Dict[str, object], new_power: str) -> str:
    title = str(item.get("new_title") or item.get("title") or "").strip()
    if title:
        return title if title in PERSON_IDENTITY_TITLES else ""
    way = str(item.get("方式") or item.get("way") or "").strip()
    if new_power == "ming" or way == "主动归附":
        return "归附"
    return "降臣"

def run_cascade() -> None:
    while True:
        changed = False
        for ev in [*content.events, *content.seed_events]:
            if not getattr(ev, "id", "") or ev.id in terminal_records:
                continue
            if not _event_dependency_ids(ev):
                continue
            reason = _event_chain_impossible_reason(ev, terminal_records, state)
            if not reason:
                continue
            db.mark_event_obsolete(
                state,
                ev.id,
                reason=reason,
                source="event_chain_invalidated",
                commit=False,
            )
            row = db.find_active_issue_by_origin("event_pool", ev.id)
            if row is not None:
                db.cancel_issue(state, int(row["id"]), narrative=f"事件链作废：{reason}", commit=False)
            item: Dict[str, object] = {"id": ev.id, "title": ev.title, "terminal_state": "obsolete", "reason": reason}
            terminalized.append(item)
            terminal_records[ev.id] = {"terminal_state": "obsolete", "terminal_reason": reason}
            changed = True
        if not changed:
            break

def _require_agno() -> None:
    from packaging.requirements import Requirement
    from packaging.utils import canonicalize_name
    from packaging.version import Version
    from ming_sim.constants import ROOT_DIR

    for raw in Path(ROOT_DIR, "requirements.txt").read_text(encoding="utf-8").splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        req = Requirement(line)
        if canonicalize_name(req.name) != "agno":
            continue
        installed = installed_distribution_version(req.name)
        if Version(installed) not in req.specifier:
            raise DependencyMismatch(
                f"installed {req.name} {installed} does not satisfy {line}",
                package=req.name,
                requirement=line,
            )
        return
    raise DependencyMismatch(
        "requirements.txt has no declaration for agno",
        package="agno",
        requirement="",
    )

def canonical_region_id_exact(
    raw: object, regions: Optional[Dict[str, Region]] = None,
) -> Optional[str]:
    """location 写缝专用：仅 compact 精确等值（id/name/region_aliases）。

    空串 → ''；未知非空 → None（调用方 fail-loud）。
    禁止子串/模糊；不调用 match_region_id_from_text。
    """
    if raw is None:
        return ""
    text = str(raw).strip()
    if not text:
        return ""
    text = _strip_controlled_namespace(text, "region")
    special = resolve_special_region_alias(text)
    if special is not None:
        return special
    key = compact_name(text)
    if not key:
        return ""
    for region in (regions or {}).values():
        candidates = [region.id, region.name, *region_aliases(region)]
        for alias in candidates:
            if compact_name(alias) == key:
                return region.id
    return None

def candidate_supply(
    db: Any, state: Any, *, exclude_dossier_ids: Optional[set[int]] = None,
) -> dict[str, list]:
    """#1893：本月可供模型挑选的人物事件与弹劾潮候选（只供事实，不代选）。

    人物事件候选走既有 ``gather_candidate_events`` 硬门（时间窗 / 状态门 /
    已发·避过·过期终态 / auto_trigger 均已在读侧排除），弹劾潮候选走既有
    ``gather_impeachment_surge_candidates`` 硬门（旨外变形暴露 × 派系 leverage）。
    两条门只给资格与结构化事实；选不选、发不发难仍由同一次月末世界段里的
    模型决定（ADR 0014 / 0091 / P6）。
    """
    from ming_sim.issues import (
        gather_candidate_events,
        gather_impeachment_surge_candidates,
    )

    events = [_candidate_event_fact(ev) for ev in gather_candidate_events(state, db)]
    excluded = set(exclude_dossier_ids or ())
    surge = [
        dict(item)
        for item in gather_impeachment_surge_candidates(state, db)
        if int(item.get("dossier_id") or 0) not in excluded  # type: ignore[arg-type]
    ]
    return {"events": events, "impeachment_surge": surge}

def _new_armies_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    for item in raw:
        if not isinstance(item, dict):
            continue
        mapped = {ARMY_FIELD_ALIASES.get(str(k).strip(), str(k).strip()): v for k, v in item.items()}
        if _nonempty_text(mapped.get("id")) and _nonzero_int(mapped.get("manpower")):
            return True
    return False

def _consume_rescript_answers(
    session: Any, chain: Dict[str, Any], *, source: Provenance,
) -> None:
    """把已裁批红接回案卷 / 请旨续推；幂等，已落不动。

    同一旨 / 同一世界段多问须全部答完才续推一次（ADR 0157 步骤 4）。
    """
    db, state = session.db, session.state
    turn = int(state.turn)
    from ming_sim.rescript_draft import consume_memorial_answers
    consume_memorial_answers(session, chain, source=source)
    rows = db.list_pending_decisions(turn)
    decided = [r for r in rows if str(r.get("status") or "") == "decided"]
    if not decided:
        return

    def _answer_from_row(row: Dict[str, object]) -> Dict[str, object]:
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        return {
            **row, "choice": dict(choice),
            "label": str(choice.get("label") or ""),
            "hint": str(choice.get("hint") or ""),
            "note": str(choice.get("note") or ""),
            "context": str(row.get("context") or ""),
            "event_id": str(row.get("event_id") or ""),
            "title": str(row.get("title") or ""),
        }

    for row in decided:
        event_id = str(row.get("event_id") or "")
        if event_id.startswith("deliberation:"):
            from ming_sim.rescript_actions import apply_imperial_deliberation_push
            original = db.get_decree_dossier(int(event_id.partition(":")[2]))
            if (row["choice"] or {}).get("action") == "imperial_push" and (original["payload"] or {}).get("deliberation_state") == "stalled":
                with atomic(db):
                    apply_imperial_deliberation_push(
                        db, state, target_dossier_id=int(original["id"]),
                        decision_key=row["decision_key"],
                        decree_text=(row.get("choice") or {}).get("note", ""),
                    )
            continue
        if not event_id.startswith("dossier:"):
            continue
        choice = row.get("choice") if isinstance(row.get("choice"), dict) else {}
        _apply_decided_triad(db, state, row, choice, content=session.content)

    world_rows = [
        r for r in rows
        if str(r.get("event_id") or "").startswith(_WORLD_QUESTION_PREFIX)
        and int(str(r["event_id"]).rsplit(":", 1)[1]) >= int(chain.get("world_question_offset", 0))
    ]
    if (
        world_rows
        and all(str(r.get("status") or "") == "decided" for r in world_rows)
        and chain.get("world_questions")
    ):
        _record_world_question_event_choices(db, state, chain, world_rows, turn=turn)
        continue_world_after_answers(
            session, chain,
            answers=[_answer_from_row(r) for r in sorted(world_rows, key=lambda r: r["answer_order"])],
            source=source,
        )

    decree_rows_by_ref: Dict[str, List[Dict[str, object]]] = {}
    for row in rows:
        event_id = str(row.get("event_id") or "")
        if not event_id.startswith(_DECREE_QUESTION_PREFIX):
            continue
        body = event_id[len(_DECREE_QUESTION_PREFIX):]
        ref, _, idx = body.rpartition(":")
        if int(idx) < int((chain.get("decree_question_offsets") or {}).get(ref, 0)):
            continue
        decree_rows_by_ref.setdefault(ref, []).append(row)
    for ref, ref_rows in decree_rows_by_ref.items():
        if not all(str(r.get("status") or "") == "decided" for r in ref_rows):
            continue
        continue_decree_after_answers(
            session, decree_ref=ref, chain=chain,
            answers=[_answer_from_row(r) for r in sorted(ref_rows, key=lambda r: r["answer_order"])],
            source=source,

def petition_verdict_grounding(db: Any, state: Any) -> list[dict[str, object]]:
    """已呈皇帝、待亲裁落定结局的三饷事项及其封闭标签集（#1892 / ADR 0143 输入侧）。

    只列事件账里已有请旨答复、终态仍空的事项。到期但尚未上疏的事项不在此列，
    转译器不得把它们写成已批。不声明结局即留中，引擎不写终态。只供事实，不代模型判断。
    """
    from ming_sim.issues import _fiscal_levy_event_by_id, petition_outcome_is_admissible

    out: list[dict[str, object]] = []
    for row in db.list_event_petition_records():
        event_id = str(row.get("event_id") or "")
        if not event_id or any(item["event_id"] == event_id for item in out):
            continue
        if not petition_outcome_is_admissible(state, db, event_id, None):
            continue
        ev = _fiscal_levy_event_by_id(event_id)
        if ev is None:
            continue
        out.append({
            "event_id": event_id,
            "title": ev.title,
            "verdict_labels": list(getattr(ev, "terminal_reason_labels", []) or []),
        })
    return out

